{
  "candidates": [
    {
      "subpart": "PPPP",
      "title": "Plastic Parts and Products Surface Coating (NESHAP)",
      "gates": [
        {
          "type": "source_category",
          "question": "Does your facility perform surface coating of plastic parts or products (including associated activities such as surface preparation, cleaning, mixing, or storage)?",
          "test": "yes -> activity matches the source category described for this subpart; no -> this subpart's source category is not matched",
          "citations": [
            "40 CFR 63.4481(a)"
          ],
          "quote": "the source category to which this subpart applies is the surface coating of any plastic parts or products, as described in paragraph (a)(1) of this section, and it includes the subcategories listed"
        },
        {
          "type": "affected_source",
          "question": "Does the operation include coating operations, storage/mixing vessels, equipment or containers used to convey coatings/thinners/cleaning materials, or storage/conveyance of wastes generated by coating operations at the facility?",
          "test": "yes -> those items constitute the affected source for this subpart; no -> those elements are not present and so this affected-source definition is not met",
          "citations": [
            "40 CFR 63.4482(b)"
          ],
          "quote": "The affected source is the collection of all of the items listed in paragraphs (b)(1) through (4) of this section that are used for surface coating of plastic parts and products within each subcategory."
        },
        {
          "type": "major_or_area",
          "question": "Is the surface-coating affected source located at, part of, or itself a major source of HAP emissions?",
          "test": "yes -> the facility is a major source (or located at/part of one) and that condition is relevant to applicability; no -> the facility is not a major source and this major-source condition is not met",
          "citations": [
            "40 CFR 63.4481(b)"
          ],
          "quote": "and that is a major source, is located at a major source, or is part of a major source of emissions of HAP."
        },
        {
          "type": "threshold",
          "question": "Does the affected source use 378 liters (100 gallons) or more per year of coatings that contain HAP in the surface coating of plastic parts and products?",
          "test": "yes -> the 378 L/yr coating-use threshold is met; no -> the coating-use threshold is not met",
          "citations": [
            "40 CFR 63.4481(b)"
          ],
          "quote": "that uses 378 liters (100 gallons (gal)) per year, or more, of coatings that contain hazardous air pollutants (HAP) in the surface coating of plastic parts and products defined in paragraph (a) of this section;"
        },
        {
          "type": "exemption",
          "question": "Is the material you apply (or the activity) outside the definition of 'coating' (i.e., not a material applied to a substrate for decorative, protective, or functional purposes, including adhesives)?",
          "test": "yes -> the material/activity may be outside the subpart's coating definition (possible exemption); no -> the material/activity meets the subpart's coating definition (not exempt on that basis)",
          "citations": [
            "40 CFR 63.4581"
          ],
          "quote": "Coating means a material applied to a substrate for decorative, protective, or functional purposes. Such materials include, but are not limited to, paints, sealants, liquid plastic coatings, caulks, inks, adhesives, and maskants."
        },
        {
          "type": "compliance_date",
          "question": "Was the coating equipment (the six additional lines or the existing lines) constructed or commenced after December 4, 2002 (i.e., would the affected source or those operations be considered new or reconstructed)?",
          "test": "yes -> the equipment/lines meet the 'new' criteria (new source) and new-source provisions may apply; no -> the equipment/lines are existing (or not reconstructed) and existing-source provisions apply",
          "citations": [
            "40 CFR 63.4482(c)(1)-(2)"
          ],
          "quote": "You commenced the construction of the source after December 4, 2002 by installing new coating equipment. The new coating equipment is used to coat plastic parts and products at a source where no plastic parts surface coating was previously performed."
        }
      ],
      "missing": [
        "Whether the methylene chloride application is considered an adhesive/coating application (applied for bonding) or instead a cleaning/other operation under the subpart definitions.",
        "Annual quantity (volume) of the methylene chloride and other HAP-containing coatings/thinners/additives/cleaning materials used in these solvent-welding operations (to determine the 378 L/yr threshold).",
        "Whether the facility (or the contiguous group of sources under common control) is a major source of HAP (metrics: tpy of single HAP and combined HAP).",
        "Whether the six added lines are new construction/reconstruction (dates of installation/start) relative to December 4, 2002.",
        "Whether the emissions from the solvent-welding step are captured/controlled or routed to add-on control devices (relevant if using emission-rate-with-controls option).",
        "Whether any specific exemption in §63.4481(c) (e.g., research facility, military, specialty process) might apply to these operations."
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions (40 CFR Part 63, Subpart A)",
      "gates": [],
      "missing": [
        "Which specific General Provisions in §§ 63.1 through 63.15 apply (see Table 2 to subpart PPPP), and any deadlines or procedural requirements from Subpart A that affect notifications, reporting, or compliance timing."
      ]
    }
  ],
  "checklist": [
    {
      "item": "Confirm whether the methylene chloride application is intended to bond parts (i.e., applied for the purpose of bonding two surfaces together) rather than solely cleaning.",
      "gate": "exemption"
    },
    {
      "item": "Measure or inventory the annual volume of methylene chloride and any other HAP-containing materials used in the solvent-welding operations (gallons or liters per year).",
      "gate": "threshold"
    },
    {
      "item": "Determine whether the facility (or group of contiguous sources under common control) is a major source of HAP (>=10 tpy single HAP or >=25 tpy combined HAP).",
      "gate": "major_or_area"
    },
    {
      "item": "Document whether the six additional lines are new or reconstructed equipment and the dates construction/installation commenced relative to Dec 4, 2002.",
      "gate": "compliance_date"
    },
    {
      "item": "Inventory whether the operations include the elements listed in §63.4482(b) (coating operations, storage/mixing vessels, conveyance equipment, waste handling) to confirm affected-source status.",
      "gate": "affected_source"
    },
    {
      "item": "Confirm whether the applied material leaves any coating solids (mass of coating solids) or is entirely solvent that evaporates with no dry film remaining.",
      "gate": "source_category"
    }
  ]
}

{
  "candidates": [
