      "title": "General Provisions (40 CFR part 63, subpart A)",
      "gates": [
        {
          "type": "source_category",
          "question": "Does the applicable subpart require you to comply with the General Provisions in 40 CFR part 63, subpart A?",
          "test": "yes -> Subpart A requirements are invoked for the affected source; no -> Subpart A requirements are not invoked by that subpart",
          "citations": [
            "40 CFR 63.11157(a)"
          ],
          "quote": "If you own or operate a new affected source, you must comply with the requirements of the General Provisions in 40 CFR part 63, subpart A as specified in Table 1 to this subpart."
