            "40 CFR 63.11153(a)"
          ],
          "quote": "You are subject to this subpart if you own or operate a new secondary copper smelter that is an area source of hazardous air pollutant (HAP) emissions."
        },
        {
          "type": "threshold",
          "question": "Was construction or reconstruction of the affected secondary copper smelter commenced on or after October 6, 2006 (i.e., is it a 'new affected source')?",
          "test": "yes -> the source is a new affected source for this subpart; no -> the source is not a 'new affected source' under this subpart",
          "citations": [
            "40 CFR 63.11153(b)"
          ],
          "quote": "Your secondary copper smelter is a new affected source if you commenced constructed or reconstruction of the affected source on or after October 6, 2006."
        },
        {
          "type": "compliance_date",
          "question": "If this is a new affected source, did startup occur after January 23, 2007?",
          "test": "yes -> compliance with this subpart is required upon startup; no -> compliance date was January 23, 2007",
          "citations": [
            "40 CFR 63.11154(b)"
          ],
          "quote": "If you startup a new affected source after January 23, 2007, you must achieve compliance with the applicable provisions of this subpart upon startup of your affected source."
        }
      ],
      "missing": [
        "Date construction/startup or reconstruction to determine new vs existing (post-October 6, 2006)",
        "Confirmation that the facility produces anode copper via a pyrometallurgical purification process (versus merely melting scrap to ingots or simple shapes)",
        "Whether the facility has been designated an area source by the permitting authority (the scenario states synthetic minor but documentary confirmation may be needed)"
      ]
    },
    {
      "subpart": "ZZZZZZ",
      "title": "Area Source Standards for Aluminum, Copper, and Other Nonferrous Foundries",
      "gates": [
        {
          "type": "source_category",
          "question": "Does your facility meet the definition of a 'copper foundry' that melts copper and pours molten copper into molds to manufacture complex castings?",
          "test": "yes -> the facility falls within the copper foundry category potentially subject to this subpart; no -> the facility is not a copper foundry under this subpart",
          "citations": [
            "40 CFR 63.11556"
          ],
          "quote": "Copper foundry means a facility that melts copper and pours molten copper into molds to manufacture copper or copper-based alloy castings (excluding die casting) that are complex shapes."
        },
        {
          "type": "affected_source",
          "question": "Does your operation pour molten copper into molds to make complex shape castings (rather than casting simple shapes like anode copper, sows, ingots, billets, bars, or copper cake)?",
          "test": "yes -> the foundry equipment-level affected source definition applies; no -> the operation may be excluded from this subpart as a primary/secondary metal producer producing simple shapes",
          "citations": [
            "40 CFR 63.11556"
          ],
          "quote": "For purposes of this subpart, this definition does not include primary or secondary metal producers that cast molten copper to produce simple shapes such as sows, ingots, billets, bars, anode copper, or copper cake."
        },
        {
          "type": "source_category",
          "question": "Is your facility an aluminum, copper, or other nonferrous foundry as described in the applicability provision?",
          "test": "yes -> the applicability criteria in this subpart must be evaluated; no -> the subpart does not apply on the basis of foundry category",
          "citations": [
            "40 CFR 63.11544(a)"
          ],
          "quote": "You are subject to this subpart if you own or operate an aluminum foundry, copper foundry, or other nonferrous foundry as defined in § 63.11556, “What definitions apply to this subpart?”"
        }
      ],
      "missing": [
        "Annual metal melt production or capacity (to determine if the foundry meets the 600 tpy threshold) and whether this is a new or existing affected source relative to February 9, 2009",
        "Whether the facility pours molten copper into molds to produce complex castings versus producing anode copper or other simple shapes"
      ]
    },
    {
      "subpart": "TTTTTT",
      "title": "Area Source Standards for Secondary Nonferrous Metals Processing Facilities",
      "gates": [
        {
          "type": "source_category",
          "question": "Is your facility a 'secondary nonferrous metals processing facility' as defined in 40 CFR 63.11472?",
          "test": "yes -> the facility may be in the industry category covered by this subpart; no -> this subpart does not apply on the basis of that industry category",
          "citations": [
            "40 CFR 63.11462(a)"
          ],
          "quote": "You are subject to this subpart if you own or operate a secondary nonferrous metals processing facility (as defined in § 63.11472) that is an area source of hazardous air pollutant (HAP) emissions."
        }
      ],
      "missing": [
        "Text of the definition in 40 CFR 63.11472 (what operations/equipment constitute a 'secondary nonferrous metals processing facility')",
        "Details tying the plant's specific processes (tilting anode furnace, fluxes, oxidation/reduction, casting anodes) to the definition in § 63.11472"
      ]
    }
  ],
  "checklist": [
    {
      "item": "Does the facility melt copper scrap and cast product into anode copper (anodes for electrolytic refining) using a pyrometallurgical process (tilting anode furnace with flux, oxidation/reduction, and casting to anodes)?",
      "gate": "affected_source"
    },
    {
      "item": "Does the facility pour molten copper into molds to manufacture complex shape castings (rather than producing simple shapes like anode copper, sows, ingots, billets, bars, or copper cake)?",
      "gate": "affected_source"
    },
    {
      "item": "Does the facility meet the definition of a 'secondary nonferrous metals processing facility' in 40 CFR 63.11472 (definition text not provided here)?",
      "gate": "affected_source"
    }
  ]
